INSERT INTO `wp_postmeta` VALUES (5327,1033,'_presentacion_del_tramite','Este trámite está dirigido a aquellos vecinos que quieran presentar un vehículo nuevo para la actividad comercial que se está realizando (remis, taxi, transporte escolar, transporte para personas con capacidades diferentes, coche escuela, o transporte de cargas generales).');
INSERT INTO `wp_postmeta` VALUES (5328,1033,'_requisitos','<ol>\n 	<li>Documentación del vehículo nuevo (dependiendo la actividad específica que realice)</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (5329,1033,'_duracion_del_tramite','½ hora en la presentación de documentación e inspección técnica. 72 (setenta y dos) horas una vez confeccionada la Habilitación firmada y controlada por el Director General de Tránsito y Transporte, para retirarla en la Oficina de Transporte.');
