INSERT INTO `wp_postmeta` VALUES (5403,1037,'_requisitos','<ol>\n 	<li>Deberá suministrar sus datos personales (N° de DNI, nombre y apellido completo, domicilio y teléfono)</li>\n 	<li>Datos de su laboral (Nombre de la Empresa, Dirección y Teléfono)</li>\n 	<li>Lugar donde debería acceder al transporte público, día y horario que debería de haber accedido al mismo.</li>\n</ol>');
