INSERT INTO `wp_postmeta` VALUES (5529,1042,'_duracion_del_tramite','Los titulares de industrias deberán solicitar ante esta Dirección el CAA, quién determinará los requisitos de documentación a presentar de la industria. Luego de una evaluación técnica de la documentación y de una inspección del establecimiento por parte de la Dirección, se podrá obtener el CAAP o CAA, según corresponda, en un plazo de 30 días.');
INSERT INTO `wp_postmeta` VALUES (5530,1042,'_vigencia_del_documento_obtenido','El Certificado de Aptitud Ambiental (Fase III) tiene una vigencia de 4 años, mientras que la vigencia del Certificado de Aptitud Ambiental de Proyecto (Fase II - CAAP) será determinada por la Autoridad de Aplicación según el caso.');
INSERT INTO `wp_postmeta` VALUES (5531,1042,'_respaldo_legal','<a href=\"http://www.opds.gba.gov.ar/sites/default/files/Ley%2011459.pdf\">Ley Provincial 11.459 de Radicación Industrial</a>\n\n<a href=\"http://www.opds.gba.gov.ar/sites/default/files/Decreto%20531-2019.pdf\">Decreto Reglamentario OPDS 531/19</a>\n<a href=\"https://normas.gba.gob.ar/documentos/xAm1N1fR.pdf\">Decreto 973/20</a>\n<a href=\"http://www.opds.gba.gov.ar/sites/default/files/LEY%2011720.pdf\">Ley Provincial 11.720 de Residuos Especiales</a>\n<a href=\"http://www.opds.gba.gov.ar/sites/default/files/RESOLUCION%20592%202000.pdf\">Resolución OPDS 592/00 – Disposición Transitoria de Residuos Especiales</a>\n<a href=\"http://www.opds.gba.gov.ar/sites/default/files/LEY%205965.pdf\">Ley 5.9 65 de Protección de Agua y Atmósfera</a>\n<a href=\"http://www.opds.gba.gov.ar/sites/default/files/Decreto%201074%2018.pdf\">Decreto Reglamentario 1074/18 (Licencia de Emisiones Gaseosas a la Atmósfera</a>\n<a href=\"http://www.ada.gba.gov.ar/sites/default/files/2020-01/RSC-2019-41907175-GDEBA-ADA.pdf\">Resolución ADA 2222/19 (Prefactibilidad Hídrica, Aptitud de Obra, y Permisos)</a>');
INSERT INTO `wp_postmeta` VALUES (5532,1042,'_observaciones','<strong>COSTO: </strong>Emisión del CAA y CAAP gratuito\n\n<strong>DOCUMENTO QUE SE OBTIENE:</strong> Certificado de Aptitud Ambiental de Proyecto (Fase II - CAAP) y/o Certificado de Aptitud Ambiental (Fase III - CAA)\n\n<strong>QUIEN LO PUEDE REALIZAR</strong>: Industrias que han sido clasificadas por el Ministerio de Ambiente de la Provincia de Buenos Aires en Primera o Segunda Categoría, según Decretos Reglamentarios de la Ley N° 11.459.\n\n<strong>INFORMACIÓN A TENER EN CUENTA:</strong> Toda la documentación e información presentada para la obtención del Certificado de Aptitud Ambiental o el Certificado de Aptitud Ambiental de Proyecto, será considerada en carácter de Declaración Jurada. El CAA es requisito obligatorio para el funcionamiento de establecimientos industriales en toda la provincia de Buenos Aires.');
INSERT INTO `wp_postmeta` VALUES (5533,1042,'_lugar_de_atencion','Subsecretaría de Ambiente, sito en D. F. Sarmiento 1551, San Miguel.');
