INSERT INTO `wp_postmeta` VALUES (5977,1065,'_presentacion_del_tramite','Una vez concluida la obra” para la cual se obtuvo el correspondiente permiso de construcción, el profesional responsable deberá presentar una declaración jurada de “Construcción Finalizada (se presenta en el trámite de informes de avance e inspecciones).');
INSERT INTO `wp_postmeta` VALUES (5978,1065,'_requisitos','<ol>\n 	<li>Ser titular del dominio o quien sustente un boleto de compra - venta y haber obtenido previamente el correspondiente permiso de obra.</li>\n 	<li>Definir un profesional responsable actuante (registrado en el Municipio).</li>\n 	<li>Presentar la información y documentación solicitada en tiempo y forma.</li>\n 	<li>Pagar las tasas y derechos que sean requeridos durante el trámite.</li>\n 	<li>Poseer el libre deuda de la partidas involucradas en el trámite</li>\n 	<li>Que la obra esté concluida y el profesional responsable haya presentado la “Declaración Jurada de Fin de Construcción”.</li>\n 	<li>Que no existan objeciones técnicas que impliquen un rechazo de la solicitud</li>\n 	<li>En caso de que haya existido una unificación o división parcelaria debe haberse completado el trámite de aprobación del nuevo plano de mensura</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (5979,1065,'_duracion_del_tramite','La duración de cada trámite será variable en función a la complejidad de cada caso en particular.');
