INSERT INTO `wp_postmeta` VALUES (6377,1084,'_presentacion_del_tramite','El objetivo del trámite es actualizar la titularidad de la TSM ya que el cambio no es automático. Esto quiere decir que, al momento de adquirir una propiedad, el impuesto de esa propiedad continua a nombre del dueño anterior hasta el momento en el que el nuevo dueño realice dicho trámite.\n\n&nbsp;');
INSERT INTO `wp_postmeta` VALUES (6378,1084,'_requisitos','<ol>\n 	<li>Boleto compra venta con la reposición fiscal + informe de dominio o copia simple de escritura</li>\n 	<li>CUIL O CUIT</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (6379,1084,'_duracion_del_tramite','Entre 3 a 10 días hábiles');
