INSERT INTO `wp_postmeta` VALUES (6552,1091,'_presentacion_del_tramite','<div>\n<div class=\"bg-secretaria border-table\">\n<p class=\"bg-secretaria border-table\">El objetivo del trámite es actualizar la titularidad de la TSM, ya que su actualización no es automática. La TSM de las propiedades se emiten a nombre del último propietario registrado hasta tanto se realice dicho trámite.</p>\n\n</div>\n</div>');
