INSERT INTO `wp_postmeta` VALUES (6752,1099,'_presentacion_del_tramite','Se debe acercar presencialmente a la Dirección de Bromatología en Sarmiento 1686.\n\nEl trámite lo pueden realizar titulares de comercios y/o industrias.\n\nPasos a seguir:\n<ol>\n 	<li>Con el turno ya asignado, el titular de la unidad debe acercarse a la Dirección de Bromatología con la documentación requerida y el vehículo, para ser inspeccionado.</li>\n 	<li>Abonar el canon anual correspondiente.</li>\n 	<li>Acercarse a la Dirección de Bromatología y retirar el certificado.</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (6753,1099,'_requisitos','Deberá presentar la siguiente documentación:\n<ul>\n 	<li>Nombre y Apellido del titular y/o razón social</li>\n 	<li>Domicilio</li>\n 	<li>Teléfono de contacto</li>\n 	<li>Días y Horarios de funcionamiento</li>\n 	<li>Rubro</li>\n</ul>');
