INSERT INTO `wp_postmeta` VALUES (7108,1116,'_respaldo_legal','<a href=\"/boletin-oficial/\" target=\"_blank\" rel=\"noopener\">Ordenanza Fiscal </a>');
INSERT INTO `wp_postmeta` VALUES (7109,1116,'_observaciones','<strong>Descripción del trámite:</strong>\n\nEl titular del inmueble deberá completar los formularios de solicitud de eximición y presentar la documentación requerida.\n\n<strong>¿Quién lo puede realizar?:</strong>\n<ul>\n 	<li>Entidades educativas públicas, nacionales y municipales</li>\n 	<li>Jubilados y pensionados</li>\n 	<li>Cuerpo de bomberos voluntarios del partido</li>\n 	<li>Veteranos de guerra y excombatientes de Malvinas</li>\n 	<li>Discapacitados, sus padres y tutores</li>\n 	<li>Asociaciones o instituciones de bien público, instituciones religiosas de todos los cultos reconocidos por el Ministerio de Relaciones Exteriores y Culto de la Nación</li>\n 	<li>Madres y/o víctimas de desaparición forzada por las fuerzas armadas con anterioridad al año 1983.</li>\n</ul>\n<strong>Costo del trámite:</strong>\n\n<a href=\"/boletin-oficial/\">SEGÚN ORDENANZA TARIFARIA Y FISCAL VIGENTE</a>');
