INSERT INTO `wp_postmeta` VALUES (7337,1140,'_presentacion_del_tramite','Este permiso se encuentra destinado a todos los comercios habilitados que deseen publicitar y/o promocionar su comercio.\n<ol>\n 	<li>Diríjase a la Dirección General de Habilitaciones para obtener los requisitos necesarios para iniciar el trámite.</li>\n 	<li>Una vez reunida toda la información y documentación requerida, preséntela en Mesa de Entrada del municipio para la creación del expediente.</li>\n 	<li>El expediente será derivado nuevamente a la Dirección de Habilitaciones para finalizar el trámite.</li>\n 	<li>Al concluir el proceso, se le entregará un recibo para abonar publicidad y propaganda.</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (7338,1140,'_requisitos','<ul>\n 	<li>Persona física mayor de 18 años que sea comerciante en el Partido de San Miguel.</li>\n 	<li>Nota solicitando la autorización para la colocación de elementos publicitarios (carteles, folletos, captación de clientes, etc.), detallando medidas de alto, ancho y otras especificaciones, con firma, aclaración y teléfono del titular.</li>\n 	<li>Si posee luces fuera del local, presentar Certificado de Electricista Matriculado que detalle la instalación.</li>\n 	<li>Fotocopia de la habilitación del comercio.</li>\n</ul>\n<strong>Según el tipo de solicitante:</strong>\n<ul>\n 	<li>Comercio unipersonal: Fotocopia del DNI del titular.</li>\n 	<li>Sociedad: Estatuto, última acta de directorio y fotocopia del DNI del socio/gerente.</li>\n 	<li>Apoderado: Poder legal y fotocopia del DNI del apoderado.</li>\n 	<li>Foto amplia del comercio y la vereda.</li>\n</ul>');
