INSERT INTO `wp_postmeta` VALUES (7362,1142,'_presentacion_del_tramite','Destinado a todo comercio habilitado y destinado a aquellos rubros que contemplen espectáculos públicos.\n<ol>\n 	<li>El comerciante debe presentar una nota detallada que incluya la siguiente información:</li>\n</ol>\n<ul>\n 	<li style=\"list-style-type: none\">\n<ul>\n 	<li>Descripción del evento.</li>\n 	<li>Lugar, fecha y horario (inicio y fin).</li>\n 	<li>Cantidad aproximada de asistentes.</li>\n 	<li>Indicar si habrá cobro de entrada.</li>\n 	<li>Confirmar si se ofrecerá servicio de buffet.</li>\n</ul>\n</li>\n</ul>\n<ol>\n 	<li style=\"list-style-type: none\"></li>\n 	<li>La nota puede presentarse de manera presencial en la Dirección General de Habilitaciones o enviarse a través del canal de WhatsApp indicado anteriormente.</li>\n 	<li>Dependiendo de las características del evento:</li>\n</ol>\n<ul>\n 	<li style=\"list-style-type: none\">\n<ul>\n 	<li>Sin cobro de entrada: La aprobación será enviada por WhatsApp.</li>\n 	<li>Con cobro de entrada: Se deberá retirar el recibo para abonar en la oficina.</li>\n</ul>\n</li>\n</ul>');
INSERT INTO `wp_postmeta` VALUES (7363,1142,'_requisitos','Persona física mayor de 18 años que posea un comercio habilitado con compatibilidad para espectáculos públicos, como:\n<ul>\n 	<li>Salones</li>\n 	<li>Boliches</li>\n 	<li>Restaurantes\no que cuenten con un anexo habilitado para espectáculos públicos.</li>\n</ul>\n<ul>\n 	<li>Nota detallada con la información solicitada.</li>\n 	<li>Habilitación Municipal del comercio.</li>\n 	<li>Según el tipo de solicitante:\n<ul>\n 	<li>Unipersonal: Fotocopia del DNI del titular.</li>\n 	<li>Sociedad: Fotocopia del DNI del presidente y estatuto.</li>\n</ul>\n</li>\n</ul>');
