INSERT INTO `wp_postmeta` VALUES (7437,1166,'_presentacion_del_tramite','El trámite de empadronamiento tiene como objetivo permitir al contribuyente realizar actividades comerciales cumpliendo los requisitos establecidos en el Decreto Nº 239/96.\n\nPasos a seguir:\n<ol>\n 	<li>Presentar la documentación requerida en la oficina de Sarmiento 1686.</li>\n 	<li>Coordinar una inspección municipal.</li>\n 	<li>Tras la inspección, se enviará el número de expediente al solicitante por WhatsApp.</li>\n 	<li>Con el número de expediente, dirigirse a Tasas Comerciales en Sarmiento 1550 (de 8:00 a 14:00 hs) para obtener la chequera de pago mensual.</li>\n 	<li>Tras registrar el primer pago, se emitirá el documento de empadronamiento.</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (7438,1166,'_requisitos','<ul>\n 	<li>Documento Nacional de Identidad (DNI).</li>\n 	<li>Contrato de Comodato o documento que acredite el uso del inmueble.</li>\n 	<li>Copia de un servicio a nombre del solicitante (luz, agua o gas)<strong>.</strong></li>\n</ul>');
INSERT INTO `wp_postmeta` VALUES (7439,1166,'_duracion_del_tramite','24 horas hábiles.');
INSERT INTO `wp_postmeta` VALUES (7440,1166,'_vigencia_del_documento_obtenido','El empadronamiento tiene una validez de 6 meses desde su emisión. Al término de este plazo, debe renovarse en la oficina de Sarmiento 1686.');
