INSERT INTO `wp_postmeta` VALUES (7562,1195,'_presentacion_del_tramite','La <strong>Consulta Previa Industrial</strong> es un paso obligatorio para habilitar una industria en el Partido de San Miguel, conforme al Código de Zonificación , la cual será evaluada desde una perspectiva técnica y administrativa por diferentes áreas intervinientes. El resultado del mismo será una <strong>Resolución de Radicación</strong> o <strong>Resolución de Denegatoria</strong> dependiendo del análisis realizado.\n\n<strong>Pasos del procedimiento:</strong>\n<ol>\n 	<li><strong>Formulario de Consulta Previa</strong>: El titular completa este formulario, disponible en el <a href=\"https://ventanillaunica.msm.gov.ar/PortalTramites/Account/Login\">Portal de Trámites.</a></li>\n 	<li>Una vez presentado, se notifica al área de <strong>Habilitaciones</strong> para caratular la consulta en el sistema.</li>\n 	<li><strong>Inspección de Consulta a Vecinos</strong>: Se realiza una inspección de los vecinos cercanos.</li>\n 	<li>El expediente es enviado a la <strong>Dirección de Medio Ambiente</strong> para determinar la <strong>Categorización de Aptitud Ambiental</strong>.</li>\n 	<li>Realizado el análisis de las diferentes areas, el expediente regresa a <strong>Habilitaciones Comerciales</strong> para la resolución de radicación o denegatoria según lo indicado en el Código de Zonificación.</li>\n 	<li>Finalmente, se notifica al solicitante para que retire <strong>personalmente</strong> la <strong>Resolución de Radicación</strong> o <strong>Denegatoria</strong>.</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (7563,1195,'_requisitos','<ol>\n 	<li><strong>Formulario</strong> indicando los datos del titular y el domicilio de la industria.</li>\n 	<li><strong>TSM</strong> (Tasa de Servicio Municipal) o <strong>Impuesto Municipal</strong> para verificar la Partida Municipal del inmueble.</li>\n 	<li><strong>Estatuto de sociedad</strong> (si corresponde).</li>\n 	<li><strong>DNI</strong> del titular.</li>\n 	<li><strong>Plano de obra aprobado</strong> o croquis del lugar.</li>\n</ol>');
INSERT INTO `wp_postmeta` VALUES (7564,1195,'_duracion_del_tramite','Aproximadamente <strong>5 dias.</strong>');
INSERT INTO `wp_postmeta` VALUES (7565,1195,'_vigencia_del_documento_obtenido','Condicionado a la vigencia de la <strong>Categorización de Aptitud Ambiental</strong>.');
