INSERT INTO `wp_postmeta` VALUES (7612,1246,'_presentacion_del_tramite','<div class=\"bg-tramite\">PRESENTACIÓN DEL TRÁMITE</div>\n<div class=\"bg-secretaria border-table\">\n<p class=\"bg-secretaria border-table\">Para conservar la condición de exento de IIBB se deberá realizar de manera anual una Declaración Jurada. Esta permite cumplir con el requisito y seguir estando exento del pago de dicho tributo.</p>\n\n</div>');
INSERT INTO `wp_postmeta` VALUES (7613,1246,'_requisitos','<ul>\n 	<li>Clave CIT activa</li>\n 	<li>Facturación mensual de los últimos 12 meses, según facturación AFIP</li>\n 	<li>Credencial de UEALASS</li>\n</ul>');
