INSERT INTO `wp_postmeta` VALUES (8063,1269,'_requisitos','<ol>\n 	<li>No debes poseer otro inmueble, el bien requerido debe ser tu vivienda única, familiar y permanente.</li>\n 	<li>Documentación que debes presentar:</li>\n</ol>\n<ul>\n 	<li>Escritura anterior</li>\n 	<li>Boleto de compra/ venta</li>\n 	<li>N.I. de los compradores y vendedores</li>\n 	<li>U.I.L/ C.U.I.T. de los compradores y vendedores</li>\n 	<li>Acta de matrimonio de los solicitantes (si son casados)</li>\n 	<li>La valuación “fiscal” (Impuesto de ARBA-consultar al momento de iniciar el trámite)</li>\n</ul>');
