INSERT INTO `wp_postmeta` VALUES (8067,1269,'_observaciones','<strong>Descripción del trámite:</strong>\n\nPresentarse en Oficina 19 de Subsecretaría de Tierras, Vivienda y Urbanismo.\n\n<strong>Documento que se obtiene:</strong>\n\nInscripción del dominio en el Registro de la Propiedad y posterior entrega de la Escritura de Titulo Perfecto.\n\n<strong>¿Quién lo puede realizar?:</strong>\n\nVecinos de San Miguel que cumplan con los requisitos.\n\n<strong>Costo del trámite:</strong>\n\nSin costo.');
