INSERT INTO `wp_postmeta` VALUES (8886,2745,'_requisitos','<ol>\n 	<li>Solicitud con datos personales completa.</li>\n 	<li>Fotocopia del DNI actualizado. Si autoriza a otra persona, fotocopia del DNI.</li>\n 	<li>Factura de un servicio público (gas, luz, teléfono, impuesto), fotocopia de la misma coincidiendo ese domicilio con el documento.</li>\n 	<li>Foto Carnet actualizada.</li>\n 	<li>Abonar $ 550 ($30 por inscripción, $20 por carnet, $500 restantes quedan pagos de 5 meses). El valor de cuota mensual es de $100.</li>\n 	<li>Referencias: datos personales de 2 familiares o vecinos.</li>\n</ol>');
