INSERT INTO `wp_posts` VALUES (1033,1,'2024-11-19 11:23:18','2024-11-19 11:23:18','Este trámite está dirigido a aquellos vecinos que quieran presentar un vehículo nuevo para la actividad comercial que se está realizando (remis, taxi, transporte escolar, transporte para personas con capacidades diferentes, coche escuela, o transporte de cargas generales).','Cambio de Material','','publish','open','open','','cambio-de-material-2','','','2024-11-19 11:23:18','2024-11-19 11:23:18','',0,'http://msm-dev.local/guia-tramites/%area_tramite%/cambio-de-material-2/',0,'tramite','',0);
