INSERT INTO `wp_posts` VALUES (1054,1,'2024-11-19 11:23:20','2024-11-19 11:23:20','Una vez concluida la obra para la cual se obtuvo el correspondiente plano de proyecto aprobado en formato papel, y dentro de los 30 días siguientes debe efectuarse este trámite de “Final de Obra”.','Final de Obra Nueva Unifamiliar – Permiso de Obra gestionado en Papel','','publish','open','open','','final-de-obra-nueva-con-permiso-en-papel-vivienda-unifamiliar','','','2024-11-19 11:23:20','2024-11-19 11:23:20','',0,'http://msm-dev.local/guia-tramites/%area_tramite%/final-de-obra-nueva-con-permiso-en-papel-vivienda-unifamiliar/',0,'tramite','',0);
