INSERT INTO `wp_posts` VALUES (1091,1,'2024-11-19 11:23:25','2024-11-19 11:23:25','El objetivo del trámite es actualizar la titularidad de la TSM, ya que su actualización no es automática. La TSM de las propiedades se emiten a nombre del último propietario registrado hasta tanto se realice dicho trámite.','Cambio de Titular de TSM','','publish','open','open','','cambio-de-titular-de-tsm','','','2024-11-19 11:23:25','2024-11-19 11:23:25','',0,'http://msm-dev.local/guia-tramites/%area_tramite%/cambio-de-titular-de-tsm/',0,'tramite','',0);
